function merge_location_now_data(_nowDataList) {
	return {
		trains: _nowDataList.flatMap((nowData) => Array.isArray(nowData.trains) ? nowData.trains : [])
	};
}

function build_combined_rosen_html(_rosenList, _rosenHtmlList) {
	const wrappedHtmlList = [];
	let homenUpText = "";
	let homenDownText = "";

	_rosenHtmlList.forEach((html, index) => {
		const wrapper = document.createElement("div");
		wrapper.innerHTML = html;
		wrapper.querySelectorAll("script").forEach((script) => script.remove());

		const upNode = wrapper.querySelector("#homenNameUpText");
		const downNode = wrapper.querySelector("#homenNameDownText");
		if (!homenUpText && upNode) homenUpText = upNode.textContent;
		if (downNode) homenDownText = downNode.textContent;
		if (upNode) upNode.remove();
		if (downNode) downNode.remove();

		wrappedHtmlList.push("<div class='rosen-segment' data-rosen='" + _rosenList[index] + "'>" + wrapper.innerHTML + "</div>");
	});

	return {
		html: wrappedHtmlList.join(""),
		homenUpText,
		homenDownText
	};
}

